cypher:
MATCH (v:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-278-4'})
WHERE NOT EXISTS { MATCH (m:Valve)-[:line_to*1..]->(v) WHERE m <> v }
RETURN DISTINCT v.tag AS tag ORDER BY tag

